<script setup lang="ts">
import {ref} from 'vue';import type {useStudentEditor} from '../composables/useStudentEditor';import {askConfirmation,confirmation} from '../composables/useConfirmation';import MessagePanel from '../components/MessagePanel.vue';import StudentForm from '../components/StudentForm.vue';import DuplicateDialog from '../components/DuplicateDialog.vue';import DeleteDialog from '../components/DeleteDialog.vue';
const props=defineProps<{state:ReturnType<typeof useStudentEditor>}>();const emit=defineEmits<{back:[];saved:[]}>();const deleting=ref(false);
async function save(reason?:string){if(await props.state.save(reason))emit('saved');}
async function remove(reason:string){if(await props.state.remove(reason)){deleting.value=false;emit('saved');}}
async function reset(){if(!props.state.dirty.value||await askConfirmation('編集内容を読込時の値へ戻しますか。'))props.state.reset();}
async function reload(){const d=props.state.data.value;if(d&&await askConfirmation('編集内容を破棄して最新情報を読み込みますか。'))await props.state.load(d.studentId,d.form.returnContextId||'');}
</script>
<template><section class="edit-page" v-if="state.data.value"><div class="pagehead"><h1>学生登録・編集</h1><span data-field-id="REG-001">学生管理番号 {{state.data.value.studentId||'新規'}}　{{state.data.value.studentId?state.data.value.permissions.update?'編集':'参照':'新規'}}</span></div><p class="editor-notice">{{state.data.value.studentId?'登録済みの学生情報です。学籍番号は変更できません。':'学生情報を入力してください。'}} <span>必須：必ず入力　条件付：該当時に入力</span></p><MessagePanel :message="state.message.value" :error="state.error.value"/>
<form @submit.prevent="save()"><StudentForm :data="state.data.value" :busy="state.busy.value" @update:form="state.data.value.form=$event" @options="state.options"/>
<p class="updated" data-field-id="REG-025"><span>更新日時 {{state.data.value.updatedAt||'－'}}</span><span>更新者 {{state.data.value.updatedBy||'－'}}</span></p>
<div class="savebar"><button v-if="state.data.value.permissions.update" data-field-id="REG-027" type="submit" class="primary" :disabled="state.busy.value">{{state.data.value.studentId?'更新':'登録'}}</button><button v-if="state.data.value.permissions.update" data-field-id="REG-028" type="button" :disabled="state.busy.value" @click="reset">{{state.data.value.studentId?'編集取消':'入力クリア'}}</button><button v-if="state.data.value.studentId" data-field-id="REG-029" type="button" :disabled="state.busy.value" @click="reload">最新情報を再読込</button><button data-field-id="REG-030" type="button" :disabled="state.busy.value" @click="$emit('back')">検索へ戻る</button><span class="spacer"></span><button v-if="state.data.value.studentId&&state.data.value.permissions.delete" data-field-id="REG-031" type="button" class="danger" :disabled="state.busy.value" @click="deleting=true">論理削除</button></div></form>
<DuplicateDialog v-if="state.duplicate.value&&!confirmation" :candidates="state.duplicate.value.candidates||[]" :count="state.duplicate.value.candidateCount||0" :busy="state.busy.value" @confirm="save" @cancel="state.cancelDuplicate"/>
<DeleteDialog v-else-if="deleting&&!confirmation" :busy="state.busy.value" :target="state.data.value.form.studentNo+' '+state.data.value.form.studentName" @confirm="remove" @cancel="deleting=false"/>
</section></template>
